python3 -c "
import json
import re

with open('/app/resources/treasury_bulletin_1998_12.json', 'r') as f:
    data = json.load(f)

# Get elements 696 and 700 (the continuation) - the table with 1995 data
elem_696 = data['document']['elements'][696]['content']
elem_700 = data['document']['elements'][700]['content']

# Parse the table from element 696 to get all country data for 1995
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.in_th = False
        self.current_tag = None
        self.rows = []
        self.current_row = []
        self.current_cell = ''
        self.in_table = False

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            self.in_table = True
        elif tag == 'tr':
            self.current_row = []
        elif tag == 'td' or tag == 'th':
            self.in_td = True
            self.current_cell = ''

    def handle_endtag(self, tag):
        if tag == 'table':
            self.in_table = False
        elif tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
        elif tag == 'td' or tag == 'th':
            self.in_td = False
            self.current_row.append(self.current_cell.strip())

    def handle_data(self, data):
        if self.in_td:
            self.current_cell += data

# Parse element 696
parser1 = TableParser()
parser1.feed(elem_696)

# Get header and find the 1995 column
header = parser1.rows[0] if parser1.rows else []
print('Header:', header)

# Find column index for Calendar year 1995
cal_1995_idx = None
for i, col in enumerate(header):
    if '1995' in col:
        cal_1995_idx = i
        break

print('1995 column index:', cal_1995_idx)

# Find rows that are not region headers (contain numeric values)
countries_1995 = []
for row in parser1.rows[1:]:
    if len(row) > cal_1995_idx:
        country = row[0]
        value = row[cal_1995_idx]
        # Skip empty rows and regional headers
        if value and value.strip() and value.strip().replace(',', '').replace('-', '').isdigit():
            try:
                val = int(value.replace(',', ''))
                countries_1995.append((country, val))
            except:
                pass

print('\\nCountries with 1995 claims (from element 696):')
for c, v in sorted(countries_1995, key=lambda x: -x[1])[:20]:
    print(f'{c}: {v}')
"

python3 -c "
import json

with open('/app/resources/treasury_bulletin_1998_12.json', 'r') as f:
    data = json.load(f)

# Get elements 696 (Europe) and 702 (Asia) tables
elem_696 = data['document']['elements'][696]['content']
elem_702 = data['document']['elements'][702]['content']

from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.current_row = []
        self.rows = []

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.current_row = []
        elif tag == 'td' or tag == 'th':
            self.in_td = True
            self.current_cell = ''

    def handle_endtag(self, tag):
        if tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
        elif tag == 'td' or tag == 'th':
            self.in_td = False
            self.current_row.append(self.current_cell.strip())

    def handle_data(self, data):
        if self.in_td:
            self.current_cell += data

# Parse both tables
parser1 = TableParser()
parser1.feed(elem_696)

parser2 = TableParser()
parser2.feed(elem_702)

# Column index for 1995
cal_1995_idx = 1

# Combine all rows
all_rows = parser1.rows + parser2.rows

# Parse all countries
countries_1995 = []
for row in all_rows:
    if len(row) > cal_1995_idx:
        country = row[0]
        value = row[cal_1995_idx]
        # Skip empty rows, regional headers, and totals
        if value and value.strip() and value.strip() != '':
            try:
                # Handle dashes and commas
                clean_val = value.replace(',', '').replace('-', '').strip()
                if clean_val.isdigit():
                    val = int(clean_val)
                    # Exclude regional aggregates and totals
                    if not any(x in country.lower() for x in ['total', 'europe', 'asia', 'africa', 'latinamerica', 'middleeast', 'caribbean']):
                        countries_1995.append((country, val))
            except:
                pass

# Sort by value descending
countries_1995.sort(key=lambda x: -x[1])

print('Top 30 countries by U.S. claims in 1995 (millions of dollars):')
for c, v in countries_1995[:30]:
    print(f'{c}: {v}')
